begin;
set local role service_role;
do $$
declare actor uuid; customer uuid; other_customer uuid; f uuid; old_stamp timestamptz; denied boolean; audit_count int;
begin
 select id into actor from crm_users where role='admin' and active and not must_change_password limit 1;
 select id into customer from customers where status='跟进中' order by id limit 1;
 select id into other_customer from customers where id<>customer order by id limit 1;
 update customers set service_assignment_mode='round_robin' where id=customer;
 perform crm_change_customer_assignment(actor,customer,'D',false,'事务测试 D 席位');
 perform crm_change_customer_assignment(actor,customer,'E',false,'事务测试 E 席位');
 if (select service_workbench from customers where id=customer)<>'E' or not exists(select 1 from service_assignment_events where customer_id=customer and to_workbench='E' and actor_id=actor) then raise exception 'Assignment transaction or audit missing';end if;
 perform crm_customer_workflow(actor,array[customer],'follow-up','{"summary":"事务验收首次跟进","communicationStatus":"客户已读未回","callbackNotRequired":true,"callbackSkipReason":"本次无需回访"}');
 select id into f from follow_ups where customer_id=customer and summary='事务验收首次跟进';
 if f is null then raise exception 'Follow-up missing';end if;
 perform crm_customer_workflow(actor,array[customer],'follow-up',jsonb_build_object('followUpId',f,'summary','事务验收修改跟进','communicationStatus','客户已读未回','callbackNotRequired',true,'callbackSkipReason','本次无需回访'));
 if not exists(select 1 from follow_up_versions where follow_up_id=f and summary='事务验收首次跟进') then raise exception 'Follow-up version missing';end if;
 denied:=false;
 begin perform crm_customer_workflow(actor,array[other_customer],'follow-up',jsonb_build_object('followUpId',f,'summary','错误覆盖','communicationStatus','客户已读未回','callbackNotRequired',true,'callbackSkipReason','错误'));exception when others then denied:=true;end;
 if not denied then raise exception 'Cross customer follow-up accepted';end if;
 perform crm_customer_workflow(actor,array[customer],'planning','{"requestType":"itinerary","status":"行程待修改","content":"修改第三日安排"}');
 if not exists(select 1 from planning_requests where customer_id=customer and content='修改第三日安排') then raise exception 'Planning request missing';end if;
 select updated_at into old_stamp from customers where id=customer;
 select count(*) into audit_count from audit_logs where customer_id=customer;
 denied:=false;
 begin perform crm_customer_workflow(actor,array[customer],'close','{"closeReason":"不存在的原因"}');exception when others then denied:=true;end;
 if not denied or (select updated_at from customers where id=customer)<>old_stamp or (select count(*) from audit_logs where customer_id=customer)<>audit_count then raise exception 'Failed workflow partially committed';end if;
 perform crm_customer_workflow(actor,array[customer],'won','{"wonAmount":1000,"wonDate":"2026-09-07"}');
 perform crm_customer_workflow(actor,array[customer],'won-info','{"wonAmount":1200,"wonDate":"2026-09-08"}');
 if not exists(select 1 from won_records where customer_id=customer and amount=1200 and won_at='2026-09-07T16:00:00Z') then raise exception 'Won companion record mismatch';end if;
 perform crm_customer_workflow(actor,array[customer],'close','{"closeReason":"客户取消出行计划"}');
 denied:=false;
 begin perform crm_customer_workflow(actor,array[customer],'planning','{"requestType":"quotation","status":"未出报价"}');exception when others then denied:=true;end;
 if not denied then raise exception 'Closed customer planning mutation accepted';end if;
 perform crm_customer_workflow(actor,array[customer],'recover','{"communicationStatus":"待首次跟进"}');
 if (select status from customers where id=customer)<>'跟进中' then raise exception 'Restore failed';end if;
 if exists(select 1 from audit_logs where customer_id=customer and xmin::text=pg_current_xact_id()::text and actor_user_id is distinct from actor) then raise exception 'Audit actor attribution mismatch';end if;
 if has_function_privilege('authenticated','crm_customer_workflow(uuid,uuid[],text,jsonb)','EXECUTE') then raise exception 'Direct workflow privilege open';end if;
 raise notice 'PASS: customer workflow atomicity, follow-up history and association, planning, won information, close/recover and actor';
end $$;
rollback;
